import { z } from "zod";
import {
  boundedText,
  currencyCodeSchema,
  dateStringSchema,
  idSchema,
  moneyAmountSchema,
} from "./primitives.js";
import {
  BudgetLineStatusSchema,
  CategoryIdSchema,
  ChecklistKindSchema,
  IdeaEffortSchema,
  MilestoneStatusSchema,
  ProvenanceEnrichmentSchema,
  TimelineTightnessSchema,
  VendorStageSchema,
} from "./enums.js";

/**
 * Structured diagnostic warnings generated by deterministic domain algorithms.
 */
export const PlanWarningSchema = z.object({
  code: z.string().min(1).max(64),
  messageKey: z.string().min(1).max(64),
  params: z.record(z.string(), z.union([z.string(), z.number()])).optional(),
});

/**
 * Inferred type of a plan warning.
 */
export type PlanWarning = z.infer<typeof PlanWarningSchema>;

/**
 * Breakdown line item for a single budget category.
 */
export const BudgetLineSchema = z.object({
  categoryId: CategoryIdSchema,
  allocatedMinor: moneyAmountSchema,
  sharePct: z.number().min(0).max(100),
  actualMinor: moneyAmountSchema,
  status: BudgetLineStatusSchema,
});

/**
 * Inferred type of a single budget line.
 */
export type BudgetLine = z.infer<typeof BudgetLineSchema>;

/**
 * Comprehensive calculated budget plan.
 */
export const BudgetPlanSchema = z.object({
  currency: currencyCodeSchema,
  totalMinor: moneyAmountSchema,
  lines: z.array(BudgetLineSchema),
  perGuestMinor: moneyAmountSchema,
  warnings: z.array(PlanWarningSchema),
});

/**
 * Inferred type of a budget plan.
 */
export type BudgetPlan = z.infer<typeof BudgetPlanSchema>;

/**
 * Single scheduled milestone event with dependency tracking.
 */
export const MilestoneSchema = z.object({
  id: idSchema,
  title: boundedText({ min: 1, max: 120 }),
  categoryId: CategoryIdSchema.optional(),
  dueDate: dateStringSchema,
  leadDays: z.number().int(),
  dependsOn: z.array(idSchema),
  critical: z.boolean(),
  status: MilestoneStatusSchema,
  done: z.boolean(),
});

/**
 * Inferred type of a timeline milestone.
 */
export type Milestone = z.infer<typeof MilestoneSchema>;

/**
 * Complete timeline schedule calculated backward from event date.
 */
export const TimelinePlanSchema = z.object({
  eventDate: dateStringSchema,
  daysAvailable: z.number().int().min(0),
  compressionFactor: z.number().min(0).max(1),
  tightness: TimelineTightnessSchema,
  milestones: z.array(MilestoneSchema),
  warnings: z.array(PlanWarningSchema),
});

/**
 * Inferred type of a timeline plan.
 */
export type TimelinePlan = z.infer<typeof TimelinePlanSchema>;

/**
 * User-curated vendor entry with stage tracking and quote reconciliation.
 */
export const VendorSchema = z.object({
  id: idSchema,
  categoryId: CategoryIdSchema,
  name: boundedText({ min: 1, max: 120 }),
  contact: boundedText({ min: 1, max: 200, allowNewlines: true }).optional(),
  stage: VendorStageSchema,
  quoteMinor: moneyAmountSchema.optional(),
  paidMinor: moneyAmountSchema.optional(),
  notes: boundedText({ min: 1, max: 500, allowNewlines: true }).optional(),
});

/**
 * Inferred type of a vendor record.
 */
export type Vendor = z.infer<typeof VendorSchema>;

/**
 * Category-specific checklist task.
 */
export const ChecklistItemSchema = z.object({
  id: idSchema,
  categoryId: CategoryIdSchema,
  kind: ChecklistKindSchema,
  text: boundedText({ min: 1, max: 200 }),
  done: z.boolean(),
});

/**
 * Inferred type of a checklist item.
 */
export type ChecklistItem = z.infer<typeof ChecklistItemSchema>;

/**
 * Category vendor evaluation guidance brief without hardcoded business entities.
 */
export const VendorBriefSchema = z.object({
  categoryId: CategoryIdSchema,
  whatToLookFor: z.array(boundedText({ min: 1, max: 200 })),
  questionsToAsk: z.array(boundedText({ min: 1, max: 200 })),
  redFlags: z.array(boundedText({ min: 1, max: 200 })),
  contractTerms: z.array(boundedText({ min: 1, max: 200 })),
});

/**
 * Inferred type of a vendor guidance brief.
 */
export type VendorBrief = z.infer<typeof VendorBriefSchema>;

/**
 * Estimated minor-unit cost range for an idea.
 */
export const IdeaEstimateMinorSchema = z
  .object({
    min: moneyAmountSchema,
    max: moneyAmountSchema,
  })
  .refine((val) => val.max >= val.min, {
    message: "Maximum estimated amount must be greater than or equal to minimum amount",
  });

/**
 * Inferred type of an idea cost estimate.
 */
export type IdeaEstimateMinor = z.infer<typeof IdeaEstimateMinorSchema>;

/**
 * Curated celebratory concept with context-driven rationale and budget compatibility flag.
 */
export const IdeaSchema = z.object({
  id: idSchema,
  categoryId: CategoryIdSchema,
  title: boundedText({ min: 1, max: 120 }),
  description: boundedText({ min: 1, max: 500, allowNewlines: true }),
  rationale: boundedText({ min: 1, max: 300 }),
  estimateMinor: IdeaEstimateMinorSchema,
  effort: IdeaEffortSchema,
  tags: z.array(boundedText({ min: 1, max: 40 })),
  accessibilityNote: boundedText({ min: 1, max: 200 }).optional(),
  fitsBudget: z.boolean().default(true),
});

/**
 * Inferred type of an idea entry.
 */
export type Idea = z.infer<typeof IdeaSchema>;

/**
 * Provenance tracking object indicating origin of baseline and AI enrichment.
 */
export const PlanProvenanceSchema = z.object({
  baseline: z.literal("calculated"),
  enrichment: ProvenanceEnrichmentSchema,
});

/**
 * Inferred type of plan provenance metadata.
 */
export type PlanProvenance = z.infer<typeof PlanProvenanceSchema>;
